actions.script:
canView = false; canUpdate = false; canManage = false; canChange = false; isMember = false; project = null; isClient = false; sharesHours = true
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
if (row != null && row.workEffortTypeEnumId === 'WetProject') {
    const all = !!vis.allProjects
    isMember = Array.from(vis.memberProjectIds || []).includes(workEffortId)
    canView = all || Array.from(vis.visibleProjectIds || []).includes(workEffortId)
    // a template is seen by those who make projects, as Settings/Templates lists it
    if (!canView && !vis.isClient && row.isTemplate === 'Y' && ec.user.isInGroup('BOSS_PROJECT_MANAGER')) canView = true
    canManage = canView && (all || Array.from(vis.managedProjectIds || []).includes(workEffortId) || ec.user.isInGroup('BOSS_PROJECT_MANAGER'))
    canUpdate = canView && (canManage || isMember) && row.statusId !== 'WeClosed'
    // a client contact sees its client projects (get#VisibleProjectInfo) and changes nothing (impl-projects.md P10)
    if (vis.isClient) { canManage = false; canUpdate = false; isMember = false }
    canChange = canManage && row.statusId !== 'WeClosed'
    isClient = !!vis.isClient
    if (isClient && canView) {
        // strict: a failure shares nothing
        ec.message.pushErrors()
        try {
            const client = ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').call() || {}
            sharesHours = !ec.message.hasError() && Array.from(client.shareHoursProjectIds || []).includes(workEffortId)
        } catch (err) { sharesHours = false } finally { ec.message.clearErrors(); ec.message.popErrors() }
    } else if (isClient) sharesHours = false
    if (canView) project = row.getMap()
    // and no cost of it (design-projects.md §1.1: clients never see costs)
    if (project && vis.isClient) for (const field of ['actualCost', 'actualClientCost', 'totalClientCostAllowed', 'costUomId']) delete project[field]
}
if (need === 'none') return
if (!canView) { ec.message.addError(ec.resource.expand('Project ${workEffortId} is not available', '', {workEffortId})); return }
if (need === 'update' && !canUpdate) {
    if ((canManage || isMember) && row.statusId === 'WeClosed') ec.service.sync()
        .name('mantle.work.WorkEffortServices.check#WorkEffortOpen').parameters({workEffortId}).call()
    else ec.message.addError(ec.resource.expand('You are not on project ${workEffortId}', '', {workEffortId}))
} else if (['manage', 'change'].includes(need) && !canManage) ec.message.addError(ec.resource.expand('Only the managers of ${workEffortId} change that', '', {workEffortId}))
else if (need === 'change') ec.service.sync().name('mantle.work.WorkEffortServices.check#WorkEffortOpen').parameters({workEffortId}).call()

const lists = ['active', 'mine', 'planned', 'onHold', 'atRisk', 'completed', 'closed', 'all']
if (!lists.includes(list)) list = 'active'
rowList = []; rowCount = 0; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0; counts = {}
for (const key of lists) counts[key] = 0
withMoney = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
const cf = ec.entity.conditionFactory
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const all = !!vis.allProjects
const visibleIds = Array.from(vis.visibleProjectIds || [])
if (!all && !visibleIds.length) return
const split = (value) => value == null || value === '' ? [] : String(value).split(',').map((id) => id.trim()).filter((id) => id)
const none = cf.makeCondition('workEffortId', 'equals', '_NONE_')
const inIds = (ids) => ids.length ? cf.makeCondition('workEffortId', 'in', ids) : none
const base = [cf.makeCondition('workEffortTypeEnumId', 'equals', 'WetProject'), cf.makeCondition('isTemplate', 'not-equals', 'Y', true)]
if (!all) base.push(cf.makeCondition('workEffortId', 'in', visibleIds))
const ended = ['WeClosed', 'WeCancelled']
const openCond = cf.makeCondition('statusId', 'not-in', ended)
// at risk: open, with the health At risk or Off track, or numbers that warn (get#ProjectStats), as Home's counter has it
const riskyIds = () => {
    const ids = []
    let find = ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition(base.concat([openCond]), 'and'))
    for (const row of find.limit(1000).list()) {
        let risky = ['WehAtRisk', 'WehOffTrack'].includes(row.healthEnumId)
        if (!risky) {
            const stats = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectStats').parameters({workEffort: row}).call() || {}
            risky = !!(stats.projectWarning || stats.projectDanger)
        }
        if (risky) ids.push(row.workEffortId)
    }
    return ids
}
const listConds = {
    active: [cf.makeCondition('statusId', 'in', ['WeApproved', 'WeInProgress'])],
    mine: [openCond, inIds(Array.from(vis.memberProjectIds || []))],
    planned: [cf.makeCondition('statusId', 'equals', 'WeInPlanning')],
    onHold: [cf.makeCondition('statusId', 'equals', 'WeOnHold')],
    atRisk: (withCounts || list === 'atRisk') ? [openCond, inIds(riskyIds())] : [openCond, none],
    completed: [cf.makeCondition('statusId', 'equals', 'WeComplete')],
    closed: [cf.makeCondition('statusId', 'in', ended)],
    all: [],
}
const topOnly = subProjects !== 'Y' && !parentWorkEffortId
const top = topOnly ? [cf.makeCondition('parentWorkEffortId', 'is-null', null)] : []
const countOf = (conds) => ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition(base.concat(conds, top), 'and')).count()
if (withCounts) for (const key of lists) counts[key] = countOf(listConds[key])

const statusIds = split(statusId)
const conds = statusIds.length ? [cf.makeCondition('statusId', 'in', statusIds)].concat(list === 'mine' ? [listConds.mine[1]] : []) : listConds[list].slice()
const words = text ? String(text).trim() : ''
if (words) conds.push(cf.makeCondition([cf.makeCondition('workEffortName', 'like', `%${words}%`, false, true),
    cf.makeCondition('workEffortId', 'like', `%${words}%`, false, true)], 'or'))
if (healthEnumId) conds.push(cf.makeCondition('healthEnumId', 'equals', healthEnumId))
if (purposeEnumId) conds.push(cf.makeCondition('purposeEnumId', 'equals', purposeEnumId))
if (parentWorkEffortId) conds.push(cf.makeCondition('parentWorkEffortId', 'equals', parentWorkEffortId))
const byRole = (partyId, roles) => Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', partyId)
        .condition('roleTypeId', 'in', roles).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('workEffortId').list())
        .map((row) => row.workEffortId)))
if (clientPartyId) conds.push(inIds(byRole(clientPartyId, ['Customer', 'ClientManager', 'ClientBilling'])))
if (managerPartyId) conds.push(inIds(byRole(managerPartyId, ['ProjectManager', 'Manager'])))
if (dueFrom != null) conds.push(cf.makeCondition('estimatedCompletionDate', 'greater-equals', dueFrom))
if (dueThru != null) conds.push(cf.makeCondition('estimatedCompletionDate', 'less-than', dueThru))

const condition = cf.makeCondition(base.concat(conds, top), 'and')
rowCount = ec.entity.find('mantle.work.effort.WorkEffort').condition(condition).count()
const sortable = ['workEffortId', 'workEffortName', 'statusId', 'priority', 'estimatedCompletionDate', 'estimatedStartDate', 'lastUpdatedStamp', 'healthEnumId']
const orderField = orderByField ? String(orderByField).replace(/^[+^]/, '') : ''
const orderBy = orderField && sortable.includes(orderField.replace(/^-/, '')) ? [orderField, 'workEffortId'] : ['priority', 'workEffortName', 'workEffortId']
const size = pageNoLimit ? Math.max(1, Math.min(rowCount, 500)) : Math.max(1, Math.min(Number(pageSize) || 25, 200))
pageSize = size
pageMaxIndex = rowCount ? Math.floor((rowCount - 1) / size) : 0
pageIndex = pageNoLimit ? 0 : Math.min(Math.max(0, Number(pageIndex) || 0), pageMaxIndex)
let find = ec.entity.find('mantle.work.effort.WorkEffort').condition(condition)
for (const field of orderBy) find = find.orderBy(field)
let page = Array.from(find.offset(pageIndex * size).limit(size).list()).map((row) => row.getMap())
pageRangeLow = rowCount ? pageIndex * size + 1 : 0
pageRangeHigh = Math.min((pageIndex + 1) * size, rowCount)
// with the sub-projects: each program's sub-projects after it (those on the page, then the others it has that the user
// sees, not templates), a sub-project whose program is on the page moved under it
if (subProjects === 'Y' && !parentWorkEffortId && page.length) {
    const onPage = new Set(page.map((row) => row.workEffortId))
    const nested = []
    for (const row of page) {
        if (row.parentWorkEffortId && onPage.has(row.parentWorkEffortId)) continue
        nested.push(row)
        const children = page.filter((other) => other.parentWorkEffortId === row.workEffortId)
        for (const child of ec.entity.find('mantle.work.effort.WorkEffort').condition('parentWorkEffortId', row.workEffortId)
                .condition(cf.makeCondition(base, 'and')).orderBy('workEffortName').limit(100).list())
            if (!onPage.has(child.workEffortId)) children.push(child.getMap())
        for (const child of children) nested.push(Object.assign({}, child, {isSubProject: true}))
    }
    page = nested
}
rowList = ec.service.sync().name('ironstone.projects.ProjectServices.decorate#ProjectRows').parameters({projectList: page, withMoney: withMoney,
    sumSubProjects: subProjects === 'Y'}).call()?.rowList || []

rowList = []
const projects = Array.from(projectList || [])
if (!projects.length) return
const cf = ec.entity.conditionFactory
const L = (text) => ec.l10n.localize(text)
const nowMillis = Number(String(ec.user.nowTimestamp))
const today = ec.user.getPeriodRange('day', '0')
const todayStart = today ? Number(String(today[0])) : nowMillis
const num = (value) => value == null ? 0 : Number(String(value))
const hours = (value) => ec.l10n.format(Math.round(value * 100) / 100, '#,##0.##')
const healthColors = {WehOnTrack: 'positive', WehAtRisk: 'warning', WehOffTrack: 'negative'}
const label = (entityName, field, id) => id ? (ec.entity.find(entityName).condition(field, id).useCache(true).one()?.description || id) : ''
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: Array.from(new Set(projects
        .map((row) => row.statusId).filter((id) => id)))}).call()?.colors || {}
const nameOf = (partyId) => {
    if (!partyId) return ''
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
    return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId) : partyId
}
const parties = (id, roles) => Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', id).condition('roleTypeId', 'in', roles)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('fromDate').list())
const hiddenItems = ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js')
const itemStats = (id) => {
    const stats = {total: 0, done: 0, open: 0, overdue: 0, actual: 0, estimated: 0, remaining: 0}
    // (a confidential issue's task the user is no Owner of is in no count: HiddenItems.js)
    for (const item of hiddenItems.without(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', id).condition('workEffortTypeEnumId', 'WetTask'))
            .selectField('statusId').selectField('estimatedCompletionDate').selectField('estimatedWorkTime').selectField('actualWorkTime')
            .selectField('remainingWorkTime').limit(10000).list()) {
        if (item.statusId === 'WeCancelled') continue
        stats.total++
        const done = item.statusId === 'WeComplete' || item.statusId === 'WeClosed'
        if (done) stats.done++
        else {
            stats.open++
            if (item.estimatedCompletionDate != null && num(item.estimatedCompletionDate) < todayStart) stats.overdue++
        }
        stats.actual += num(item.actualWorkTime); stats.estimated += num(item.estimatedWorkTime); stats.remaining += num(item.remainingWorkTime)
    }
    return stats
}
const byId = new Map()
for (const project of projects) {
    const id = project.workEffortId
    const stats = itemStats(id)
    byId.set(id, stats)
    const client = parties(id, ['Customer'])[0]
    const managers = parties(id, ['ProjectManager', 'Manager'])
    const manager = managers.find((row) => row.roleTypeId === 'ProjectManager') || managers[0]
    const managerUser = manager ? ec.entity.find('moqui.security.UserAccount').condition('partyId', manager.partyId).selectField('userId').disableAuthz().list()[0] : null
    const milestone = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', id).condition('workEffortTypeEnumId', 'WetMilestone')
            .condition(cf.makeCondition('statusId', 'not-in', ['WeComplete', 'WeClosed', 'WeCancelled'], true))
            .condition('estimatedCompletionDate', 'is-not-null', null).orderBy('estimatedCompletionDate').limit(1).list())[0]
    const budget = num(project.totalTimeAllowed)
    let budgetUsedText = ''
    let warning = false
    if (withMoney) {
        const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectStats').parameters({workEffort: project}).call() || {}
        if (num(project.totalClientCostAllowed) > 0) budgetUsedText = ec.l10n.format(Math.round(num(out.clientBudgetUsedPercent)), '#,##0') + '%'
        warning = !!(out.projectWarning || out.projectDanger)
    }
    rowList.push({workEffortId: id, workEffortName: project.workEffortName || id, url: '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(id),
        description: project.description || '', parentWorkEffortId: project.parentWorkEffortId || null, isSubProject: !!project.isSubProject,
        clientPartyId: client?.partyId || null, clientName: client ? nameOf(client.partyId) : '',
        managerPartyId: manager?.partyId || null, managerName: manager ? nameOf(manager.partyId) : '', managerUserId: managerUser?.userId || null,
        statusId: project.statusId || null, statusLabel: label('moqui.basic.StatusItem', 'statusId', project.statusId), statusColor: colors[project.statusId] || 'grey-7',
        colorName: project.colorName || null,
        healthEnumId: project.healthEnumId || null, healthLabel: label('moqui.basic.Enumeration', 'enumId', project.healthEnumId),
        healthColor: healthColors[project.healthEnumId] || 'grey-7', purposeLabel: label('moqui.basic.Enumeration', 'enumId', project.purposeEnumId),
        nextMilestoneId: milestone?.workEffortId || null, nextMilestoneName: milestone?.workEffortName || '',
        nextMilestoneText: milestone ? (milestone.workEffortName || milestone.workEffortId) + ' · ' + ec.l10n.format(milestone.estimatedCompletionDate, 'MMM d') : '',
        totalTimeAllowed: budget, budgetUsedText: budgetUsedText, warning: warning || (budget > 0 && stats.actual + stats.remaining > budget),
        hoursOver: budget > 0 && stats.actual + stats.remaining > budget,
        subProjectCount: ec.entity.find('mantle.work.effort.WorkEffort').condition('parentWorkEffortId', id).condition('workEffortTypeEnumId', 'WetProject')
            .condition(cf.makeCondition('isTemplate', 'not-equals', 'Y', true)).count(),
        estimatedStartDate: project.estimatedStartDate ?? null, estimatedCompletionDate: project.estimatedCompletionDate ?? null,
        dueText: project.estimatedCompletionDate != null ? ec.l10n.format(project.estimatedCompletionDate, 'MMM d, yyyy') : '',
        updatedText: project.lastUpdatedStamp != null ? ec.l10n.format(project.lastUpdatedStamp, 'MMM d') : ''})
}
// the numbers of a row: its own, or with sumSubProjects its own and those of its sub-projects in the list
for (const row of rowList) {
    const stats = Object.assign({}, byId.get(row.workEffortId))
    if (sumSubProjects && !row.isSubProject) for (const child of rowList) if (child.parentWorkEffortId === row.workEffortId) {
        const more = byId.get(child.workEffortId)
        for (const key of Object.keys(stats)) stats[key] += more[key]
    }
    const percent = stats.total ? Math.round(stats.done * 100 / stats.total) : 0
    const of = row.totalTimeAllowed > 0 ? row.totalTimeAllowed : stats.estimated
    Object.assign(row, {openItems: stats.open, overdueItems: stats.overdue, itemCount: stats.total, doneCount: stats.done, percentDone: percent,
        progressText: stats.total ? percent + '% · ' + stats.done + '/' + stats.total : '—',
        hoursActual: stats.actual, hoursEstimated: stats.estimated, hoursRemaining: stats.remaining,
        hoursText: of > 0 ? hours(stats.actual) + ' ' + L('of') + ' ' + hours(of) + ' h' : (stats.actual > 0 ? hours(stats.actual) + ' h' : '—'),
        hoursPercent: of > 0 ? Math.min(100, Math.round(stats.actual * 100 / of)) : 0,
        itemsText: stats.open + (stats.overdue ? ' · ' + stats.overdue + ' ' + L('overdue') : '')})
}

doneCount = 0; failedCount = 0
const failures = []
const ids = (Array.isArray(workEffortIds) ? workEffortIds : String(workEffortIds || '').split(',')).map((id) => String(id).trim()).filter((id) => id)
if (!['manager', 'hold', 'close'].includes(action)) { ec.message.addError(ec.resource.expand('${action} is not a bulk change', '', {action})); return }
if (!ids.length) { ec.message.addError(ec.l10n.localize('Select one or more projects first')); return }
if (action === 'manager' && !value) { ec.message.addError(ec.l10n.localize('Choose the manager')); return }
for (const id of ids) {
    ec.message.pushErrors()
    let reason = null
    try {
        const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: id, need: 'none'}).call() || {}
        if (!access.canView) reason = ec.l10n.localize('not available')
        else if (!access.canManage) reason = ec.l10n.localize('you do not manage it')
        else if (action === 'manager') ec.service.sync().name('mantle.work.WorkEffortServices.replace#WorkEffortParty').parameters({workEffortId: id,
            roleTypeId: 'ProjectManager', newPartyId: value, statusId: 'WeptAssigned'}).requireNewTransaction(true).call()
        else {
            const steps = action === 'hold' ? ['WeOnHold'] : (access.project.statusId === 'WeComplete' ? ['WeClosed'] : ['WeComplete', 'WeClosed'])
            for (const statusId of steps) {
                ec.service.sync().name('ironstone.projects.ProjectServices.set#ProjectStatus').parameters({workEffortId: id, statusId: statusId}).requireNewTransaction(true).call()
                if (ec.message.hasError()) break
            }
        }
        if (!reason && ec.message.hasError()) reason = ec.message.getErrorsString()
    } catch (err) {
        reason = String(err && err.message ? err.message : err)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (reason) {
        failedCount++
        failures.push(id + ' ' + reason)
        ec.logger.warn(`Projects bulk ${action}: ${id} skipped: ${reason}`)
    } else doneCount++
}
message = ec.resource.expand('${count} projects changed', '', {count: doneCount}) + (failedCount ? ec.resource.expand('; ${count} skipped: ${reasons}', '',
    {count: failedCount, reasons: failures.join(', ')}) : '')

const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'manage'}).call() || {}
if (ec.message.hasError()) return
const project = access.project
if (project.statusId === statusId) { message = ec.l10n.localize('No change'); return }
const move = ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', 'Default').condition('statusId', project.statusId)
        .condition('toStatusId', statusId).useCache(true).one()
const toText = ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).useCache(true).one()?.description || statusId
if (move == null) {
    const fromText = ec.entity.find('moqui.basic.StatusItem').condition('statusId', project.statusId).useCache(true).one()?.description || project.statusId
    ec.message.addError(ec.resource.expand('A project does not go from ${fromText} to ${toText}', '', {fromText, toText}))
    return
}
const fields = {workEffortId: workEffortId, statusId: statusId}
if (statusId === 'WeInProgress' && project.actualStartDate == null) fields.actualStartDate = ec.user.nowTimestamp
if (statusId === 'WeComplete') fields.actualCompletionDate = ec.user.nowTimestamp
ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters(fields).call()
if (ec.message.hasError()) return
message = ec.resource.expand('${name} is ${toText}', '', {name: project.workEffortName || workEffortId, toText})

visible = false; header = {}
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'none'}).call() || {}
if (!access.canView) return
visible = true
const project = access.project
const L = (text) => ec.l10n.localize(text)
const row = (ec.service.sync().name('ironstone.projects.ProjectServices.decorate#ProjectRows').parameters({projectList: [project], withMoney: !!access.canManage}).call()?.rowList || [])[0] || {}
const latest = Array.from(ec.entity.find('mantle.work.effort.WorkEffortUpdate').condition('workEffortId', workEffortId).orderBy('-updateDate').limit(1).list())[0]
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId}).call()?.settings || {}
const moves = Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', 'Default').condition('statusId', project.statusId)
        .useCache(true).list()).filter((move) => String(move.toStatusId).startsWith('We'))
const primaries = {WeInPlanning: 'WeApproved', WeApproved: 'WeInProgress', WeOnHold: 'WeInProgress', WeComplete: 'WeClosed', WeClosed: 'WeInPlanning', WeCancelled: 'WeInPlanning'}
const primaryTo = primaries[project.statusId] || null
const primaryMove = primaryTo ? moves.find((move) => move.toStatusId === primaryTo) : null
const ended = ['WeClosed', 'WeCancelled'].includes(project.statusId)
// impl-projects.md P8a: the billable time not invoiced, for a manager of the project who manages money
let unbilledText = ''
if (access.canManage && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('TIME_ENTRY_RATE'))) {
    ec.message.pushErrors()
    try {
        const unbilled = Array.from(ec.service.sync().name('mantle.work.ProjectServices.get#UnbilledSummary').parameters({workEffortId: workEffortId}).call()?.projectList || [])[0]
        if (unbilled && !ec.message.hasError()) unbilledText = ec.l10n.formatCurrency(toDecimal(unbilled.amount), unbilled.currencyUomId || 'USD')
    } catch (err) { ec.logger.error(`Project header of ${workEffortId}: the unbilled amount is left out: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
header = Object.assign({}, row, {
    canManage: !!access.canManage, canChange: !!access.canChange, canUpdate: !!access.canUpdate, isMember: !!access.isMember,
    isTemplate: project.isTemplate === 'Y', isEnded: ended,
    statusFlowId: project.statusFlowId || 'Default',
    stageStatusIds: ['WeInPlanning', 'WeApproved', 'WeInProgress', 'WeComplete', 'WeClosed'],
    healthDateText: latest ? ec.l10n.format(latest.updateDate, 'MMM d') : '',
    primaryAction: project.statusId === 'WeInProgress' ? {kind: 'update', label: L('Post update')}
        : primaryMove ? {kind: 'status', statusId: primaryMove.toStatusId, label: L(primaryMove.transitionName || primaryMove.toStatusId)} : null,
    otherMoves: moves.filter((move) => move.toStatusId !== (project.statusId === 'WeInProgress' ? null : primaryTo))
            .map((move) => ({statusId: move.toStatusId, label: L(move.transitionName || move.toStatusId)})),
    modules: String(settings.WstModules || '').split(',').map((key) => key.trim()).filter((key) => key),
    unbilledText: unbilledText,
    description: project.description || '', visibilityEnumId: project.visibilityEnumId || null,
    startText: project.estimatedStartDate != null ? ec.l10n.format(project.estimatedStartDate, 'MMM d, yyyy') : ''})

overview = {updateList: [], milestoneList: [], statusCountList: [], topItemList: [], timeBudget: null, memberList: [], repositoryList: [],
    activityList: [], activityMore: false, failedBoxes: []}
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId}).call() || {}
if (ec.message.hasError()) return
const project = access.project
const cf = ec.entity.conditionFactory
const L = (text) => ec.l10n.localize(text)
const num = (value) => value == null || value === '' ? 0 : Number(String(value))
const hours = (value) => ec.l10n.format(Math.round(value * 100) / 100, '#,##0.##')
const healthColors = {WehOnTrack: 'positive', WehAtRisk: 'warning', WehOffTrack: 'negative'}
const enumText = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
const statusText = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
const nameOf = (partyId) => {
    if (!partyId) return ''
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
    return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId) : partyId
}
const box = (name, run) => {
    ec.message.pushErrors()
    try { run() } catch (err) {
        overview.failedBoxes.push(name)
        ec.logger.error(`Overview of project ${workEffortId}: the ${name} box failed and is left empty: ${err && err.message ? err.message : err}`)
    } finally {
        if (ec.message.hasError()) { overview.failedBoxes.push(name); ec.logger.warn(`Overview of project ${workEffortId}, ${name}: ${ec.message.getErrorsString()}`) }
        ec.message.clearErrors(); ec.message.popErrors()
    }
}
const tabUrl = (more) => '/qapps/Projects/Projects/ProjectDetail/WorkItems?workEffortId=' + encodeURIComponent(workEffortId) + (more || '')

box('status', () => {
    for (const update of ec.entity.find('mantle.work.effort.WorkEffortUpdate').condition('workEffortId', workEffortId).orderBy('-updateDate').limit(4).list()) {
        const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', update.communicationEventId).one()
        overview.updateList.push({communicationEventId: update.communicationEventId, dateText: ec.l10n.format(update.updateDate, 'MMM d, yyyy'),
            healthEnumId: update.healthEnumId, healthLabel: enumText(update.healthEnumId), healthColor: healthColors[update.healthEnumId] || 'grey-7',
            percentComplete: update.percentComplete, percentText: update.percentComplete != null ? update.percentComplete + '%' : '',
            clientVisible: update.clientVisible === 'Y', authorName: nameOf(event?.fromPartyId), subject: event?.subject || '', body: event?.body || ''})
    }
})
box('milestones', () => {
    for (const plan of ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId)
            .condition('workEffortTypeEnumId', 'in', ['WetMilestone', 'WetRelease']).condition(cf.makeCondition('statusId', 'not-in', ['WeComplete', 'WeClosed', 'WeCancelled'], true))
            .orderBy('estimatedCompletionDate').orderBy('workEffortName').limit(3).list()) {
        const type = plan.workEffortTypeEnumId === 'WetRelease' ? 'WeatRelease' : 'WeatMilestone'
        const itemIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', plan.workEffortId)
                .condition('workEffortAssocTypeEnumId', type).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('toWorkEffortId').list()).map((row) => row.toWorkEffortId)
        let total = 0, done = 0
        if (itemIds.length) for (const item of ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', itemIds)).selectField('statusId').list()) {
            if (item.statusId === 'WeCancelled') continue
            total++
            if (item.statusId === 'WeComplete' || item.statusId === 'WeClosed') done++
        }
        overview.milestoneList.push({workEffortId: plan.workEffortId, workEffortName: plan.workEffortName || plan.workEffortId,
            typeLabel: plan.workEffortTypeEnumId === 'WetRelease' ? L('Release') : L('Milestone'), statusId: plan.statusId, statusLabel: statusText(plan.statusId),
            dueText: plan.estimatedCompletionDate != null ? ec.l10n.format(plan.estimatedCompletionDate, 'MMM d, yyyy') : '—',
            progress: total ? Math.round(done * 100 / total) : 0, progressText: done + '/' + total,
            url: (type === 'WeatRelease' ? '/qapps/Projects/Projects/ReleaseDetail' : '/qapps/Projects/Projects/MilestoneDetail') + '?workEffortId=' + encodeURIComponent(plan.workEffortId)})
    }
    const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: overview.milestoneList.map((row) => row.statusId)}).call()?.colors || {}
    for (const row of overview.milestoneList) row.statusColor = colors[row.statusId] || 'grey-7'
})
let stats = null
box('work', () => {
    stats = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectStats').parameters({workEffort: project}).call() || {}
    const byStatus = stats.taskCountByStatusMap || {}
    const ids = Array.from(ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId', 'WorkEffort').orderBy('sequenceNum').useCache(true).list())
            .map((row) => row.statusId).filter((id) => num(byStatus[id]) > 0)
    const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: ids}).call()?.colors || {}
    overview.statusCountList = ids.map((id) => ({statusId: id, label: statusText(id), count: num(byStatus[id]), color: colors[id] || 'grey-7',
        url: tabUrl('&list=all&statusId=' + encodeURIComponent(id))}))
    overview.itemCount = overview.statusCountList.reduce((sum, row) => sum + row.count, 0)
})
box('breakdown', () => {
    const out = ec.service.sync().name('mantle.work.ProjectServices.get#WorkItemTree').parameters({rootWorkEffortId: workEffortId, topLevel: true}).call() || {}
    const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: Array.from(out.workItemList || [])
            .map((row) => row.statusId)}).call()?.colors || {}
    for (const row of Array.from(out.workItemList || []).slice(0, 12)) {
        const estimate = num(row.totalEstimatedWorkTime)
        const used = num(row.totalActualWorkTime) + num(row.totalRemainingWorkTime)
        const budget = num(row.totalBudget)
        overview.topItemList.push({workEffortId: row.workEffortId, workEffortName: row.workEffortName || row.workEffortId, statusId: row.statusId,
            statusLabel: statusText(row.statusId), statusColor: colors[row.statusId] || 'grey-7', estimateText: estimate ? hours(estimate) + ' h' : '—',
            usedText: hours(num(row.totalActualWorkTime)) + ' + ' + hours(num(row.totalRemainingWorkTime)) + ' h',
            usedPercent: estimate ? Math.min(100, Math.round(used * 100 / estimate)) : 0,
            barColor: budget && used > budget ? 'negative' : estimate && used > estimate ? 'warning' : 'primary',
            doneText: (num(row.doneCount) + (['WeComplete', 'WeClosed'].includes(row.statusId) ? 1 : 0)) + '/' + (num(row.itemCount) + 1),
            url: tabUrl('&list=all&view=tree&underWorkEffortId=' + encodeURIComponent(row.workEffortId))})
    }
})
if (access.canManage) box('time', () => {
    const sums = {estimated: 0, actual: 0, remaining: 0}
    for (const item of ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).condition('workEffortTypeEnumId', 'WetTask'))
            .condition('statusId', 'not-equals', 'WeCancelled').selectField('estimatedWorkTime').selectField('actualWorkTime').selectField('remainingWorkTime').limit(10000).list()) {
        sums.estimated += num(item.estimatedWorkTime); sums.actual += num(item.actualWorkTime); sums.remaining += num(item.remainingWorkTime)
    }
    const budget = num(project.totalTimeAllowed)
    const clientBudget = num(project.totalClientCostAllowed)
    const st = stats || ec.service.sync().name('mantle.work.ProjectServices.get#ProjectStats').parameters({workEffort: project}).call() || {}
    const over = budget > 0 && sums.actual + sums.remaining > budget
    overview.timeBudget = {estimatedText: hours(sums.estimated) + ' h', actualText: hours(sums.actual) + ' h', remainingText: hours(sums.remaining) + ' h',
        budgetText: budget ? hours(budget) + ' h' : L('No hours budget'), hoursPercent: budget ? Math.min(100, Math.round(sums.actual * 100 / budget)) : 0,
        forecastPercent: budget ? Math.min(100, Math.round((sums.actual + sums.remaining) * 100 / budget)) : 0, hasBudget: budget > 0,
        clientBudgetText: clientBudget ? ec.l10n.formatCurrency(clientBudget, project.costUomId || 'USD') : '',
        clientUsedText: clientBudget ? ec.l10n.format(Math.round(num(st.clientBudgetUsedPercent)), '#,##0') + '%' : '',
        profitText: num(project.actualClientCost) || num(project.actualCost) ? ec.l10n.formatCurrency(num(st.actualProfit), project.costUomId || 'USD') : '',
        flag: over || st.projectDanger ? 'danger' : st.projectWarning ? 'warning' : '',
        flagText: over ? L('The hours pass the budget') : st.projectDanger ? L('Over the estimate or the client budget') : st.projectWarning ? L('Spending ahead of the work done') : ''}
})
// a client contact (impl-projects.md P10b): no internal members, and the hours of the breakdown only when the project shares them
if (access.isClient) {
    overview.clientView = true
    overview.sharesHours = !!access.sharesHours
}
if (access.isClient) {
    if (!access.sharesHours) for (const row of overview.topItemList) Object.assign(row, {estimateText: '', usedText: '', usedPercent: 0, barColor: 'primary'})
} else box('members', () => {
    const people = new Map()
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('fromDate').list()) {
        if (['Customer', 'CustomerBillTo', 'ClientManager', 'ClientBilling', 'Vendor', 'VendorBillFrom'].includes(row.roleTypeId)) continue
        const role = ec.entity.find('mantle.party.RoleType').condition('roleTypeId', row.roleTypeId).useCache(true).one()?.description || row.roleTypeId
        if (!people.has(row.partyId)) {
            const user = ec.entity.find('moqui.security.UserAccount').condition('partyId', row.partyId).selectField('userId').disableAuthz().list()[0]
            people.set(row.partyId, {partyId: row.partyId, name: nameOf(row.partyId), userId: user?.userId || null, roles: []})
        }
        people.get(row.partyId).roles.push(role)
    }
    overview.memberList = Array.from(people.values()).map((row) => Object.assign(row, {roleText: row.roles.join(', ')}))
})
box('repositories', () => {
    const ids = Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', workEffortId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()).map((row) => row.repositoryId)))
    if (!ids.length) return
    // git hosting is a build feature: without it no repositories, and no failed call to leave the request rollback-only
    if (!ec.service.sync().name('ironstone.projects.CodeServices.get#CodeHosting').call()?.available) return
    const found = ec.service.sync().name('org.moqui.git.GitServices.find#GitRepositories').parameters({repositoryIdList: ids, pageNoLimit: true}).call() || {}
    for (const repo of Array.from(found.repositoryList || [])) {
        let urls = {}
        try { urls = ec.service.sync().name('org.moqui.git.GitServices.get#GitCloneUrls').parameters({repositoryId: repo.repositoryId}).call() || {} }
        catch (err) { ec.logger.warn(`Overview of project ${workEffortId}: no clone URLs of ${repo.repositoryId}: ${err}`) }
        overview.repositoryList.push({repositoryId: repo.repositoryId, description: repo.description || '', branch: repo.branch || '',
            kindLabel: repo.repositoryKind === 'db' ? L('In the database') : repo.repositoryKind === 'remote' ? L('Mirror') : L('On disk'),
            lastText: repo.lastUpdateDate != null ? ec.l10n.format(repo.lastUpdateDate, 'MMM d, yyyy') : L('No pushes yet'),
            httpsUrl: urls.httpsUrl || '', sshUrl: urls.sshUrl || ''})
    }
})
box('activity', () => {
    const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectActivity').parameters({workEffortId: workEffortId, pageSize: 10}).call() || {}
    overview.activityList = Array.from(out.activityList || []).map((entry) => Object.assign({}, entry, {whenText: entry.date ? ec.l10n.format(new Date(entry.date), 'MMM d, h:mm a') : '',
        itemUrl: entry.workEffortId === workEffortId ? '' : '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(entry.workEffortId),
        icon: {status: 'sym_o_flag', comment: 'sym_o_chat_bubble', update: 'sym_o_campaign', commit: 'sym_o_commit'}[entry.kind] || 'sym_o_history'}))
    overview.activityMore = !!out.hasMore
})

memberList = []; teamList = []; clientList = []; roleOptions = []
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId}).call() || {}
if (ec.message.hasError()) return
canManage = !!access.canChange
const clientRoles = ['Customer', 'CustomerBillTo', 'ClientManager', 'ClientBilling']
const other = clientRoles.concat(['Vendor', 'VendorBillFrom', 'OrgTeam'])
const roleText = (id) => ec.entity.find('mantle.party.RoleType').condition('roleTypeId', id).useCache(true).one()?.description || id
const day = (value) => value == null ? '' : ec.l10n.format(value, 'MMM d, yyyy')
for (const row of ec.entity.find('mantle.party.RoleGroupMember').condition('roleGroupEnumId', 'RgpProject').useCache(true).list())
    if (!other.includes(row.roleTypeId)) roleOptions.push({key: row.roleTypeId, text: roleText(row.roleTypeId)})
roleOptions.sort((a, b) => a.text.localeCompare(b.text))
for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
        .condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null)).orderBy('fromDate').list()) {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', row.partyId).one()
    const name = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || row.partyId) : row.partyId
    const user = ec.entity.find('moqui.security.UserAccount').condition('partyId', row.partyId).selectField('userId').selectField('username').disableAuthz().list()[0]
    const entry = {partyId: row.partyId, name: name, roleTypeId: row.roleTypeId, roleText: roleText(row.roleTypeId), fromText: day(row.fromDate),
        fromDate: row.fromDate, userId: user?.userId || null, hasUser: !!user, statusText: row.statusId ? (ec.entity.find('moqui.basic.StatusItem')
            .condition('statusId', row.statusId).useCache(true).one()?.description || row.statusId) : ''}
    if (row.roleTypeId === 'Vendor' || row.roleTypeId === 'VendorBillFrom') continue
    if (row.roleTypeId === 'OrgTeam') teamList.push(entry)
    else if (clientRoles.includes(row.roleTypeId)) {
        const email = ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', row.partyId)
                .condition('contactMechTypeEnumId', 'CmtEmailAddress').conditionDate('fromDate', 'thruDate', null).list()[0]
        entry.email = email?.infoString || ''
        entry.signInText = user ? ec.l10n.localize('Has a user') : ''
        clientList.push(entry)
    } else memberList.push(entry)
}

ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call()
if (ec.message.hasError()) return
const inGroup = ec.entity.find('mantle.party.RoleGroupMember').condition('roleGroupEnumId', 'RgpProject').condition('roleTypeId', roleTypeId).useCache(true).one()
if (inGroup == null || roleTypeId === 'Vendor' || roleTypeId === 'VendorBillFrom') { ec.message.addError(ec.resource.expand('${roleTypeId} is not a project role', '', {roleTypeId})); return }
const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
if (party == null) { ec.message.addError(ec.resource.expand('Party ${partyId} not found', '', {partyId})); return }
ec.service.sync().name('mantle.work.WorkEffortServices.add#WorkEffortParty').parameters({workEffortId: workEffortId, partyId: partyId, roleTypeId: roleTypeId,
    statusId: ['Customer', 'CustomerBillTo', 'OrgTeam'].includes(roleTypeId) ? null : 'WeptAssigned'}).call()
if (ec.message.hasError()) return
const name = party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId
const role = ec.entity.find('mantle.party.RoleType').condition('roleTypeId', roleTypeId).useCache(true).one()?.description || roleTypeId
message = ec.resource.expand('${name} added as ${role}', '', {name, role})

const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call() || {}
if (ec.message.hasError()) return
const dayOf = (text, label) => {
    const value = text == null ? '' : String(text).trim().substring(0, 10)
    if (!value) return null
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) { ec.message.addError(ec.resource.expand('${label} is not a date (yyyy-MM-dd)', '', {label})); return null }
    return ec.l10n.parseTimestamp(value + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
}
const start = dayOf(estimatedStartDate, ec.l10n.localize('The start'))
const due = dayOf(estimatedCompletionDate, ec.l10n.localize('The target date'))
if (ec.message.hasError()) return
const program = parentWorkEffortId ? String(parentWorkEffortId).trim() : ''
if (program) {
    let at = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', program).one()
    if (at == null || at.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(ec.resource.expand('${program} is not a project', '', {program})); return }
    for (let depth = 0; at != null && depth < 50; depth++) {
        if (at.workEffortId === workEffortId) { ec.message.addError(ec.l10n.localize('A project cannot be under itself or one of its sub-projects')); return }
        at = at.parentWorkEffortId ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', at.parentWorkEffortId).one() : null
    }
}
const name = String(workEffortName).trim()
if (!name) { ec.message.addError(ec.l10n.localize('A project needs a name')); return }
ec.service.sync().name('mantle.work.ProjectServices.update#Project').parameters({workEffortId: workEffortId, workEffortName: name,
    purposeEnumId: purposeEnumId || null, priority: priority && /^[1-9]$/.test(String(priority)) ? Number(priority) : null,
    visibilityEnumId: visibilityEnumId || null, parentWorkEffortId: program || null, estimatedStartDate: start, estimatedCompletionDate: due,
    colorName: colorName || null, description: description || null, clientPartyId: clientPartyId || null}).call()
if (!ec.message.hasError()) message = ec.l10n.localize('Project saved')

ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call()
if (ec.message.hasError()) return
const listOf = (value) => value == null ? [] : (Array.isArray(value) ? value : (typeof value === 'object' && value.length != null ? Array.from(value) : String(value).split(',')))
        .map((part) => String(part).trim()).filter((part) => part)
const store = (type, value) => ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: workEffortId,
    settingTypeEnumId: type, settingValue: value}).call()
if (box === 'modules' || modules != null) {
    const known = ['backlog', 'requests', 'code', 'docs', 'time', 'money', 'client']
    const chosen = listOf(modules).filter((key) => known.includes(key))
    store('WstModules', known.filter((key) => chosen.includes(key)).join(','))
}
if (box === 'workItems' || workItemTypes != null) {
    const types = listOf(workItemTypes)
    const known = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').call()?.typeList || []).map((row) => row.enumId)
    const unknown = types.filter((id) => !known.includes(id))
    if (unknown.length) { ec.message.addError(ec.resource.expand('Not a work item type: ${ids}', '', {ids: unknown.join(', ')})); return }
    if (box === 'workItems' && !types.length) { ec.message.addError(ec.l10n.localize('Offer at least one work item type')); return }
    if (types.length) store('WstWorkItemTypes', types.join(','))
}
if (statusFlowId) {
    if (!['Default', 'WorkEffortDevelopment'].includes(statusFlowId)) { ec.message.addError(ec.resource.expand('${statusFlowId} is not a work item flow', '', {statusFlowId})); return }
    ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: workEffortId, statusFlowId: statusFlowId}).call()
}
if (estimateUnit) {
    if (!['hours', 'points'].includes(estimateUnit)) { ec.message.addError(ec.l10n.localize('The estimate unit is hours or points')); return }
    store('WstEstimateUnit', estimateUnit)
}
if (branchPattern != null) {
    const pattern = String(branchPattern).trim()
    if (pattern && (pattern.length > 120 || !/<(id|n)>/.test(pattern))) { ec.message.addError(ec.l10n.localize('A branch pattern names the work item: <id>, or <KEY>-<n>')); return }
    if (pattern) store('WstBranchPattern', pattern)
    else ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', workEffortId).condition('settingTypeEnumId', 'WstBranchPattern').deleteAll()
}
const flags = {severalSprints: 'WstSeveralSprints', shareNewItems: 'WstShareNewItems', keywordComplete: 'WstKeywordComplete',
    requestFromWork: 'WstRequestFromWork', clientSignIn: 'WstClientSignIn', shareRepositories: 'WstShareRepositories', mergeRequestMoves: 'WstMergeRequestMoves'}
const given = {severalSprints, shareNewItems, keywordComplete, requestFromWork, clientSignIn, shareRepositories, mergeRequestMoves}
for (const [key, type] of Object.entries(flags)) {
    const value = given[key]
    if (value == null || value === '') continue
    store(type, value === 'Y' || value === 'true' || value === true ? 'Y' : 'N')
}
if (!ec.message.hasError()) message = ec.l10n.localize('Settings saved')

if (!ec.user.isInGroup('BOSS_PROJECT_MANAGER') && !ec.user.isInGroup('ADMIN')) { ec.message.addError(ec.l10n.localize('Only project managers make templates')); return }
if (baseWorkEffortId) {
    ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: baseWorkEffortId}).call()
    if (ec.message.hasError()) return
}
const key = String(workEffortId || '').trim().toUpperCase()
if (!/^[A-Z0-9]{1,8}$/.test(key)) { ec.message.addError(ec.l10n.localize('A project key is one to eight letters or digits')); return }
const orgId = ec.service.sync().name('ironstone.projects.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId || null
ec.service.sync().name('mantle.work.ProjectServices.create#ProjectTemplate').parameters({workEffortId: key, workEffortName: String(workEffortName).trim(),
    baseWorkEffortId: baseWorkEffortId || null, ownerPartyId: orgId}).call()
if (ec.message.hasError()) return
templateId = key
message = ec.resource.expand('Template ${key} made', '', {key})

const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call() || {}
if (ec.message.hasError()) return
const info = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectSettingsInfo').parameters({workEffortId: workEffortId}).call()?.info || {}
if (!info.canDelete) { ec.message.addError(ec.l10n.localize('Only a project with no work items, time, invoices or commits is deleted; close or cancel it instead')); return }
const name = access.project.workEffortName || workEffortId
const ids = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).selectField('workEffortId').list())
        .map((row) => row.workEffortId).concat([workEffortId])
for (const entityName of ['mantle.work.effort.WorkEffortSetting', 'mantle.work.effort.WorkEffortUpdate', 'mantle.work.effort.WorkEffortCommEvent',
        'mantle.work.effort.WorkEffortGitRepository', 'mantle.work.effort.WorkEffortCategoryAppl'])
    ec.entity.find(entityName).condition('workEffortId', 'in', ids).deleteAll()
ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', 'in', ids).deleteAll()
ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', 'in', ids).deleteAll()
ec.service.sync().name('mantle.work.WorkEffortServices.delete#WorkEffort').parameters({workEffortId: workEffortId, deleteChildWorkEfforts: true,
    deleteWorkEffortParties: true}).call()
if (!ec.message.hasError()) message = ec.resource.expand('${name} deleted', '', {name})

if (!ec.user.isInGroup('BOSS_PROJECT_MANAGER') && !ec.user.isInGroup('ADMIN')) {
    ec.message.addError(ec.l10n.localize('Only project managers make projects'))
    return
}
const name = String(workEffortName || '').trim()
if (!name) { ec.message.addError(ec.l10n.localize('A project needs a name')); return }
const taken = (id) => ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one() != null
let key = String(workEffortId || '').trim().toUpperCase()
if (!key) {
    const words = name.toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').split(/\s+/).filter((word) => word)
    const base = (words.length > 1 ? words.map((word) => word[0]).join('') : (words[0] || 'P')).substring(0, 6) || 'P'
    key = base
    for (let n = 2; taken(key) && n < 100; n++) key = base + n
}
if (!/^[A-Z0-9]{1,8}$/.test(key)) { ec.message.addError(ec.l10n.localize('A project key is one to eight letters or digits')); return }
if (taken(key)) { ec.message.addError(ec.resource.expand('The key ${key} is taken', '', {key})); return }
if (!['WevGeneral', 'WevWorkGroup', 'WevAllUsers'].includes(visibilityEnumId)) { ec.message.addError(ec.l10n.localize('Choose who sees the project')); return }
const dayOf = (text) => {
    const value = text == null ? '' : String(text).trim().substring(0, 10)
    if (!value) return null
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) { ec.message.addError(ec.resource.expand('Not a date: ${value}; use yyyy-MM-dd', '', {value})); return null }
    return ec.l10n.parseTimestamp(value + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
}
const start = dayOf(estimatedStartDate)
const due = dayOf(estimatedCompletionDate)
if (ec.message.hasError()) return
if (start != null && due != null && Number(String(due)) < Number(String(start))) { ec.message.addError(ec.l10n.localize('The target date is before the start')); return }
if (parentWorkEffortId) {
    const program = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', parentWorkEffortId).one()
    if (program == null || program.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(ec.resource.expand('${parentWorkEffortId} is not a project', '', {parentWorkEffortId})); return }
}
const me = ec.user.userAccount?.partyId || null
const manager = managerPartyId || me
const orgId = ec.service.sync().name('ironstone.projects.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId || null
const purpose = purposeEnumId || (clientPartyId ? 'WepPrClient' : null)
if (cloneFromWorkEffortId) {
    ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: cloneFromWorkEffortId}).call()
    if (ec.message.hasError()) return
}
const baseId = templateWorkEffortId || cloneFromWorkEffortId
if (baseId) {
    const template = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', baseId).one()
    if (template == null || (templateWorkEffortId && template.isTemplate !== 'Y')) { ec.message.addError(ec.resource.expand('${baseId} is not a template', '', {baseId})); return }
    ec.service.sync().name('mantle.work.ProjectServices.clone#Project').parameters({baseWorkEffortId: baseId, workEffortId: key,
        workEffortName: name, isTemplate: 'N', visibilityEnumId: visibilityEnumId, ownerPartyId: orgId, purposeEnumId: purpose || template.purposeEnumId || null,
        estimatedStartDate: start, estimatedCompletionDate: due, parentWorkEffortId: parentWorkEffortId || null,
        description: description || template.description || null}).call()
    if (ec.message.hasError()) return
    if (orgId) ec.service.sync().name('mantle.work.WorkEffortServices.add#WorkEffortParty').parameters({workEffortId: key, partyId: orgId, roleTypeId: 'Vendor'}).call()
    if (clientPartyId) ec.service.sync().name('mantle.work.WorkEffortServices.add#WorkEffortParty').parameters({workEffortId: key, partyId: clientPartyId,
        roleTypeId: 'Customer'}).call()
} else {
    ec.service.sync().name('mantle.work.ProjectServices.create#Project').parameters({workEffortId: key, workEffortName: name, visibilityEnumId: visibilityEnumId,
        ownerPartyId: orgId, vendorPartyId: orgId, clientPartyId: clientPartyId || null, purposeEnumId: purpose,
        estimatedStartDate: start, estimatedCompletionDate: due, parentWorkEffortId: parentWorkEffortId || null, description: description || null}).call()
}
if (ec.message.hasError()) return
if (manager) ec.service.sync().name('mantle.work.WorkEffortServices.add#WorkEffortParty').parameters({workEffortId: key, partyId: manager,
    roleTypeId: 'ProjectManager', statusId: 'WeptAssigned'}).call()
if (ec.message.hasError()) return
projectId = key
url = '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(key)
message = ec.resource.expand('Project ${key} made: ${name}', '', {key, name})

const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call() || {}
if (ec.message.hasError()) return
const project = access.project
ec.service.sync().name('ironstone.projects.ProjectServices.save#ProjectSettingValues').parameters({workEffortId: workEffortId, box: 'modules', modules: modules,
    estimateUnit: estimateUnit || null, statusFlowId: statusFlowId || null}).call()
if (ec.message.hasError()) return
const parts = [ec.l10n.localize('Modules saved')]
if (repositoryChoice === 'local' || repositoryChoice === 'db') {
    const out = ec.service.sync().name('mantle.work.GitServices.create#ProjectRepository').parameters({workEffortId: workEffortId,
        repositoryId: repositoryId ? String(repositoryId).trim() : null, repositoryKind: repositoryChoice, description: project.workEffortName}).call() || {}
    if (ec.message.hasError()) return
    repositoryId = out.repositoryId
    parts.push(ec.resource.expand('repository ${repositoryId} made', '', {repositoryId}))
} else if (repositoryChoice === 'link') {
    if (!linkRepositoryId) { ec.message.addError(ec.l10n.localize('Choose the repository to link')); return }
    const viewable = ec.service.sync().name('org.moqui.git.GitServices.find#GitRepositories').parameters({repositoryIdList: [linkRepositoryId]}).call()?.repositoryList || []
    if (ec.message.hasError()) return
    if (!Array.from(viewable).length) { ec.message.addError(ec.resource.expand('Repository ${linkRepositoryId} is not available', '', {linkRepositoryId})); return }
    ec.service.sync().name('mantle.work.GitServices.add#ProjectRepository').parameters({workEffortId: workEffortId, repositoryId: linkRepositoryId}).call()
    if (ec.message.hasError()) return
    repositoryId = linkRepositoryId
    parts.push(ec.resource.expand('repository ${linkRepositoryId} linked', '', {linkRepositoryId}))
}
if (docsChoice === 'db' || docsChoice === 'repository') {
    const own = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition({workEffortId: workEffortId, settingTypeEnumId: 'WstDocsWikiSpace'}).one()
    if (own?.settingValue) wikiSpaceId = own.settingValue
    else {
        // in the repository: the one made or linked here, else the project's first
        let docsRepositoryId = null
        if (docsChoice === 'repository') {
            docsRepositoryId = (repositoryChoice !== 'none' ? repositoryId : null) || Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', workEffortId)
                    .conditionDate('fromDate', 'thruDate', null).orderBy('repositoryId').list())[0]?.repositoryId || null
            if (!docsRepositoryId) { ec.message.addError(ec.l10n.localize('Documentation in the repository needs a repository: make or link one')); return }
        }
        wikiSpaceId = ec.service.sync().name('mantle.work.ProjectServices.create#ProjectDocsSpace').parameters({workEffortId: workEffortId,
            storage: docsChoice, repositoryId: docsRepositoryId}).call()?.wikiSpaceId
        if (ec.message.hasError()) return
        parts.push(docsRepositoryId ? ec.resource.expand('documentation space ${wikiSpaceId} made in ${docsRepositoryId}', '', {wikiSpaceId, docsRepositoryId})
                : ec.resource.expand('documentation space ${wikiSpaceId} made', '', {wikiSpaceId}))
    }
}
message = parts.join(', ')

const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call() || {}
if (ec.message.hasError()) return
const amount = (value, label) => {
    const text = value == null ? '' : String(value).trim().replace(/,/g, '')
    if (!text) return null
    if (!/^\d+(\.\d+)?$/.test(text)) { ec.message.addError(ec.resource.expand('${label} is not a number', '', {label})); return null }
    return Number(text)
}
const hours = amount(totalTimeAllowed, ec.l10n.localize('The hours budget'))
const client = amount(totalClientCostAllowed, ec.l10n.localize('The client budget'))
if (ec.message.hasError()) return
if (billingBasis && !['TimeAndMaterials', 'FixedPrice', 'Milestones', 'NotBilled'].includes(billingBasis)) {
    ec.message.addError(ec.resource.expand('${billingBasis} is not a billing basis', '', {billingBasis})); return }
const fields = {workEffortId: workEffortId, totalTimeAllowed: hours, totalClientCostAllowed: client, timeUomId: access.project.timeUomId || 'TF_hr'}
if (client != null) fields.costUomId = costUomId || access.project.costUomId || ec.user.getPreference('CurrencyDefault') || 'USD'
ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters(fields).call()
if (billingBasis) ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: workEffortId,
    settingTypeEnumId: 'WstBillingBasis', settingValue: billingBasis}).call()
if (!ec.message.hasError()) message = ec.l10n.localize('Budget saved')

const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call() || {}
if (ec.message.hasError()) return
if (!['RaprClient', 'RaprVendor'].includes(ratePurposeEnumId)) { ec.message.addError(ec.l10n.localize('A rate is for client billing or worker pay')); return }
if (ratePurposeEnumId === 'RaprVendor' && partyId && Array.from(ec.service.sync().name('mantle.humanres.EmploymentServices.get#PayRateAccess')
        .parameters({partyIdList: [partyId]}).disableAuthz().call()?.lockedPartyIds || []).includes(partyId)) {
    ec.message.addError(ec.l10n.localize('The worker pay rate of an employee is their pay: only payroll sets it')); return }
const text = String(rateAmount).trim().replace(/,/g, '')
if (!/^\d+(\.\d+)?$/.test(text)) { ec.message.addError(ec.l10n.localize('The rate is a number')); return }
rateAmountId = ec.service.sync().name('mantle.humanres.RateServices.create#RateAmount').parameters({workEffortId: workEffortId, ratePurposeEnumId: ratePurposeEnumId,
    rateTypeEnumId: 'RatpStandard', partyId: partyId || null, workTypeEnumId: workTypeEnumId || null, emplPositionClassId: emplPositionClassId || null,
    rateAmount: Number(text), rateCurrencyUomId: rateCurrencyUomId || access.project.costUomId || 'USD', timePeriodUomId: 'TF_hr',
    fromDate: ec.user.nowTimestamp}).call()?.rateAmountId
if (!ec.message.hasError()) message = ec.l10n.localize('Rate added')

ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'change'}).call()
if (ec.message.hasError()) return
const rate = ec.entity.find('mantle.humanres.rate.RateAmount').condition('rateAmountId', rateAmountId).one()
if (rate == null || rate.workEffortId !== workEffortId) { ec.message.addError(ec.resource.expand('Rate ${rateAmountId} is not one of this project', '', {rateAmountId})); return }
if (rate.ratePurposeEnumId === 'RaprVendor' && rate.partyId && Array.from(ec.service.sync().name('mantle.humanres.EmploymentServices.get#PayRateAccess')
        .parameters({partyIdList: [rate.partyId]}).disableAuthz().call()?.lockedPartyIds || []).includes(rate.partyId)) {
    ec.message.addError(ec.l10n.localize('The worker pay rate of an employee is their pay: only payroll sets it')); return }
ec.service.sync().name('update#mantle.humanres.rate.RateAmount').parameters({rateAmountId: rateAmountId, thruDate: ec.user.nowTimestamp}).call()
if (!ec.message.hasError()) message = ec.l10n.localize('Rate ended')

const managers = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
home = {isManager: managers, counts: {}, atRiskProjectIds: [], workItemList: [], activityList: [], projectList: [], reviewList: [], hosting: false,
    firstRun: false, failedParts: [], timer: null, approvalList: [], myWorkProgress: null}
const part = (name, run) => {
    ec.message.pushErrors()
    try { run() } catch (err) {
        home.failedParts.push(name)
        ec.logger.error(`Projects home: ${name} failed and is left out: ${err && err.message ? err.message : err}`)
    } finally {
        if (ec.message.hasError()) { home.failedParts.push(name); ec.logger.warn(`Projects home, ${name}: ${ec.message.getErrorsString()}`) }
        ec.message.clearErrors(); ec.message.popErrors()
    }
}
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
home.firstRun = !vis.allProjects && !Array.from(vis.visibleProjectIds || []).length
part('counts', () => {
    const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectHomeCounts').parameters({managers: managers}).call() || {}
    home.counts = out.counts || {}
    home.atRiskProjectIds = Array.from(out.atRiskProjectIds || [])
    if (home.counts.myOpen != null && home.counts.myDoneRecent != null) {
        const openCount = Number(home.counts.myOpen), doneCount = Number(home.counts.myDoneRecent)
        const total = openCount + doneCount
        home.myWorkProgress = {done: doneCount, open: openCount, total: total, percent: total ? Math.round(doneCount / total * 100) : 0}
    }
})
part('time', () => {
    const out = ec.service.sync().name('ironstone.projects.TimeServices.get#HomeTime').parameters({managers: managers}).call() || {}
    home.timer = out.timer || null
    home.approvalList = Array.from(out.approvalList || [])
})
// impl-projects.md P7: the requested allocations the user decides, after the weeks
part('allocations', () => {
    if (!managers) return
    const rows = Array.from(ec.service.sync().name('ironstone.projects.ResourceServices.get#HomeAllocations').call()?.approvalList || [])
    home.approvalList = home.approvalList.concat(rows)
})
part('reviews', () => {
    home.hosting = !!ec.service.sync().name('ironstone.projects.CodeServices.get#CodeHosting').call()?.available
    if (!home.hosting || !ec.user.userId) return
    const out = ec.service.sync().name('org.moqui.git.GitReviewServices.find#MergeRequests').parameters({waitingForUserId: ec.user.userId, pageSize: 5}).call() || {}
    if (ec.message.hasError()) return
    home.reviewList = ec.service.sync().name('ironstone.projects.CodeServices.decorate#MergeRequestRows').parameters({mergeRequestList: Array.from(out.mergeRequestList || [])})
            .call()?.rowList || []
})
part('workItems', () => {
    const out = ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: 'mine', orderByField: 'estimatedCompletionDate',
        pageSize: 40, withCounts: false}).call() || {}
    // by due date, those with none last, then priority
    const rows = Array.from(out.rowList || [])
    const due = (row) => row.estimatedCompletionDate == null ? Number.MAX_SAFE_INTEGER : Number(String(row.estimatedCompletionDate))
    rows.sort((a, b) => due(a) - due(b) || Number(a.priority ?? 5) - Number(b.priority ?? 5))
    home.workItemList = rows.slice(0, 10)
})
const projectIds = (() => {
    const managed = Array.from(vis.managedProjectIds || [])
    const member = Array.from(vis.memberProjectIds || [])
    return managers && managed.length ? managed : member
})()
const open = projectIds.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds)
        .condition('workEffortTypeEnumId', 'WetProject').condition('statusId', 'not-in', ['WeClosed', 'WeCancelled'])
        .condition(ec.entity.conditionFactory.makeCondition('isTemplate', 'not-equals', 'Y', true)).orderBy('priority').orderBy('workEffortName').limit(12).list())
        .map((row) => row.getMap()) : []
part('activity', () => {
    const entries = []
    for (const project of open.slice(0, 6)) {
        const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectActivity').parameters({workEffortId: project.workEffortId, pageSize: 10}).call() || {}
        for (const entry of Array.from(out.activityList || [])) entries.push(Object.assign({}, entry, {projectId: project.workEffortId,
            projectName: project.workEffortName || project.workEffortId}))
    }
    entries.sort((a, b) => b.date - a.date)
    home.activityList = entries.slice(0, 10).map((entry) => Object.assign(entry, {whenText: entry.date ? ec.l10n.format(new Date(entry.date), 'MMM d, h:mm a') : '',
        url: entry.workEffortId === entry.projectId ? '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(entry.projectId)
            : '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(entry.workEffortId),
        icon: {status: 'sym_o_flag', comment: 'sym_o_chat_bubble', update: 'sym_o_campaign', commit: 'sym_o_commit'}[entry.kind] || 'sym_o_history'}))
})
part('projects', () => {
    home.projectList = ec.service.sync().name('ironstone.projects.ProjectServices.decorate#ProjectRows').parameters({projectList: open, withMoney: managers}).call()?.rowList || []
})

const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
organizationPartyId = ec.user.context?.activeOrgId || Array.from(vis.orgIds || [])[0] || null
if (organizationPartyId) {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', organizationPartyId).one()
    organizationName = party?.organizationName || organizationPartyId
}

typeList = []; offeredList = []; fromProject = false
const icons = {WepTask: 'sym_o_task_alt', WepFix: 'sym_o_bug_report', WepNewFeature: 'sym_o_new_releases', WepFeatureEnhance: 'sym_o_trending_up',
    WepFeatureTest: 'sym_o_science', WepDocument: 'sym_o_description', WepSupport: 'sym_o_support_agent', WepResearch: 'sym_o_travel_explore',
    WepDeployment: 'sym_o_rocket_launch', WepDevelopment: 'sym_o_code'}
const defaults = ['WepTask', 'WepFix', 'WepNewFeature', 'WepFeatureEnhance', 'WepDocument', 'WepSupport']
organizationPartyId = ec.service.sync().name('ironstone.projects.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId || null
let appSetting = {}
if (organizationPartyId) {
    const row = ec.entity.find('mantle.party.PartySetting').condition('partyId', organizationPartyId).condition('partySettingTypeId', 'ProjWorkItemTypes').one()
    if (row?.settingValue) {
        try { const parsed = JSON.parse(row.settingValue); if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) appSetting = parsed }
        catch (err) { ec.logger.error(`Work item types of ${organizationPartyId}: the ProjWorkItemTypes setting is not JSON, skipped: ${err}`) }
    }
}
const chosenIcons = appSetting.icons && typeof appSetting.icons === 'object' ? appSetting.icons : {}
let offered = null
if (rootWorkEffortId) {
    const value = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: rootWorkEffortId}).call()?.settings?.WstWorkItemTypes
    if (value) { offered = String(value).split(',').map((id) => id.trim()).filter((id) => id); fromProject = true }
}
if (offered == null && appSetting.offered) offered = String(appSetting.offered).split(',').map((id) => id.trim()).filter((id) => id)
if (offered == null) offered = defaults
const candidates = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkEffortPurpose').useCache(true).list())
        .filter((row) => (row.parentEnumId === 'WetTask' && !['WepToDo', 'WepCommunication', 'WepPlaceholder'].includes(row.enumId))
            || ['WepSupport', 'WepResearch', 'WepDevelopment', 'WepDeployment'].includes(row.enumId))
for (const row of candidates) {
    const at = offered.indexOf(row.enumId)
    typeList.push({enumId: row.enumId, label: row.description || row.enumId, icon: chosenIcons[row.enumId] || icons[row.enumId] || 'sym_o_task_alt',
        offered: at >= 0, sequence: at >= 0 ? at + 1 : null, isOwn: !icons[row.enumId] && row.enumId.startsWith('WepOrg')})
}
typeList.sort((a, b) => (a.offered === b.offered ? 0 : a.offered ? -1 : 1) || (a.sequence ?? 0) - (b.sequence ?? 0) || a.label.localeCompare(b.label))
offeredList = offered.map((id) => typeList.find((row) => row.enumId === id)).filter((row) => row)

ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const info = ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').call() || {}
const orgId = info.organizationPartyId
if (!orgId) { ec.message.addError(ec.l10n.localize('You belong to no organization, so there is nowhere to keep the setting')); return }
const known = Array.from(info.typeList || []).map((row) => row.enumId)
const list = (offered == null ? Array.from(info.offeredList || []).map((row) => row.enumId) : (Array.isArray(offered) ? offered : (typeof offered === 'object' && offered.length != null
        ? Array.from(offered) : String(offered).split(',')))).map((id) => String(id).trim()).filter((id) => id)
const unknown = list.filter((id) => !known.includes(id))
if (unknown.length) { ec.message.addError(ec.resource.expand('Not a work item type: ${ids}', '', {ids: unknown.join(', ')})); return }
if (!list.length) { ec.message.addError(ec.l10n.localize('Offer at least one work item type')); return }
let current = {}
const row = ec.entity.find('mantle.party.PartySetting').condition('partyId', orgId).condition('partySettingTypeId', 'ProjWorkItemTypes').one()
if (row?.settingValue) { try { current = JSON.parse(row.settingValue) || {} } catch (err) { current = {} } }
const value = {offered: Array.from(new Set(list)).join(',')}
const iconMap = Object.assign({}, current.icons || {})
if (icons) for (const [id, icon] of Object.entries(icons)) {
    if (!known.includes(id)) continue
    if (icon && !/^sym_o_[a-z0-9_]+$/.test(String(icon))) { ec.message.addError(ec.resource.expand('${icon} is not an icon name (sym_o_...)', '', {icon})); return }
    if (icon) iconMap[id] = String(icon); else delete iconMap[id]
}
if (Object.keys(iconMap).length) value.icons = iconMap
ec.service.sync().name('store#mantle.party.PartySetting').parameters({partyId: orgId, partySettingTypeId: 'ProjWorkItemTypes', settingValue: JSON.stringify(value)}).call()
if (!ec.message.hasError()) message = ec.l10n.localize('Work item types saved')

ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const name = String(label).trim()
if (!name) { ec.message.addError(ec.l10n.localize('A type needs a label')); return }
const info = ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').call() || {}
if (Array.from(info.typeList || []).some((row) => String(row.label).toLowerCase() === name.toLowerCase())) {
    ec.message.addError(ec.resource.expand('There is a type ${name} already', '', {name})); return }
enumId = 'WepOrg' + ec.entity.sequencedIdPrimary('moqui.basic.Enumeration.WepOrg', null, null)
ec.service.sync().name('create#moqui.basic.Enumeration').parameters({enumId: enumId, enumTypeId: 'WorkEffortPurpose', parentEnumId: 'WetTask',
    description: name}).call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.projects.ProjectServices.store#WorkItemTypes').parameters({offered: Array.from(info.offeredList || []).map((row) => row.enumId).concat([enumId]),
    icons: icon ? Object.fromEntries([[enumId, icon]]) : null}).call()
if (!ec.message.hasError()) message = ec.resource.expand('Type ${name} added', '', {name})

const statuses = Array.from(ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId', 'WorkEffort').orderBy('sequenceNum').list())
const ids = statuses.map((row) => row.statusId)
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: ids}).call()?.colors || {}
const text = (id) => statuses.find((row) => row.statusId === id)?.description || id
statusList = statuses.map((row) => ({statusId: row.statusId, description: row.description || row.statusId, sequenceNum: row.sequenceNum,
    statusColor: row.statusColor || '', colorShown: colors[row.statusId] || 'grey-7'}))
const flowIds = new Set(['Default', 'WorkEffortDevelopment'])
for (const row of ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusId', 'in', ids).selectField('statusFlowId').distinct(true).list()) flowIds.add(row.statusFlowId)
flowList = []
for (const id of flowIds) {
    const flow = ec.entity.find('moqui.basic.StatusFlow').condition('statusFlowId', id).one()
    if (flow == null) continue
    flowList.push({statusFlowId: id, description: flow.description || id, projectCount: ec.entity.find('mantle.work.effort.WorkEffort')
        .condition('workEffortTypeEnumId', 'WetProject').condition('statusFlowId', id).count(),
        transitionCount: ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', id).condition('statusId', 'in', ids).count()})
}
flowList.sort((a, b) => (a.statusFlowId === 'Default' ? -1 : b.statusFlowId === 'Default' ? 1 : a.statusFlowId.localeCompare(b.statusFlowId)))
transitionList = Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', statusFlowId).condition('statusId', 'in', ids)
        .condition('toStatusId', 'in', ids).list()).map((row) => ({statusFlowId: row.statusFlowId, statusId: row.statusId, toStatusId: row.toStatusId,
            fromText: text(row.statusId), toText: text(row.toStatusId), transitionName: row.transitionName || '', fromSeq: Number(String(statuses.find((s) => s.statusId === row.statusId)?.sequenceNum ?? 0))}))
        .sort((a, b) => a.fromSeq - b.fromSeq || a.toText.localeCompare(b.toText))

ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const status = (id) => ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).one()
const from = status(statusId), to = status(toStatusId)
if (from?.statusTypeId !== 'WorkEffort' || to?.statusTypeId !== 'WorkEffort') { ec.message.addError(ec.l10n.localize('A work flow moves between work statuses')); return }
if (statusId === toStatusId) { ec.message.addError(ec.l10n.localize('A move goes to another status')); return }
if (ec.entity.find('moqui.basic.StatusFlow').condition('statusFlowId', statusFlowId).one() == null) { ec.message.addError(ec.resource.expand('No flow ${statusFlowId}', '', {statusFlowId})); return }
const pk = {statusFlowId: statusFlowId, statusId: statusId, toStatusId: toStatusId}
const existing = ec.entity.find('moqui.basic.StatusFlowTransition').condition(pk).one()
if (remove === 'Y') {
    if (existing != null) existing.delete()
    message = ec.resource.expand('${from} to ${to} taken out', '', {from: from.description, to: to.description})
    return
}
const name = String(transitionName || '').trim() || to.description
ec.service.sync().name('store#moqui.basic.StatusFlowTransition').parameters(Object.assign({transitionName: name}, pk)).call()
if (!ec.message.hasError()) message = ec.resource.expand('${from} to ${to}: ${name}', '', {from: from.description, to: to.description, name})

ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).one()
if (status?.statusTypeId !== 'WorkEffort') { ec.message.addError(ec.resource.expand('${statusId} is not a work status', '', {statusId})); return }
if (statusColor && !['grey-7', 'primary', 'warning', 'positive', 'negative', 'info'].includes(statusColor)) {
    ec.message.addError(ec.resource.expand('${statusColor} is not a status color', '', {statusColor})); return }
const fields = {statusId: statusId, statusColor: statusColor || null}
if (description != null && String(description).trim()) fields.description = String(description).trim()
if (sequenceNum != null && String(sequenceNum).trim() !== '') {
    if (!/^\d{1,4}$/.test(String(sequenceNum).trim())) { ec.message.addError(ec.l10n.localize('The sequence is a whole number')); return }
    fields.sequenceNum = Number(String(sequenceNum).trim())
}
ec.service.sync().name('update#moqui.basic.StatusItem').parameters(fields).call()
if (!ec.message.hasError()) message = ec.resource.expand('${name} saved', '', {name: fields.description || status.description})

ec.service.sync().name('ironstone.projects.ProjectServices.check#SettingsManager').call()
if (ec.message.hasError()) return
const info = ec.service.sync().name('ironstone.projects.ProjectServices.get#Labels').call() || {}
const mine = new Set(Array.from(info.labelList || []).map((row) => row.workEffortCategoryId))
const check = (id) => { if (!mine.has(id)) ec.message.addError(ec.resource.expand('${id} is not one of your labels', '', {id})); return mine.has(id) }
const T = 'mantle.work.TaskServices.'
if (action === 'create') {
    ec.service.sync().name(T + 'create#Label').parameters({description: description || '', colorName: colorName || 'grey', ownerPartyId: info.organizationPartyId}).call()
    if (!ec.message.hasError()) message = ec.resource.expand('Label ${description} added', '', {description})
} else if (action === 'update') {
    if (!check(workEffortCategoryId)) return
    ec.service.sync().name(T + 'update#Label').parameters({workEffortCategoryId, description: description ?? null, colorName: colorName || null}).call()
    if (!ec.message.hasError()) message = ec.l10n.localize('Label saved')
} else if (action === 'delete') {
    if (!check(workEffortCategoryId)) return
    const out = ec.service.sync().name(T + 'delete#Label').parameters({workEffortCategoryId}).call() || {}
    if (!ec.message.hasError()) message = ec.resource.expand('Label deleted; taken off ${count} work items', '', {count: out.itemCount || 0})
} else if (action === 'merge') {
    if (!check(fromCategoryId) || !check(intoCategoryId)) return
    const out = ec.service.sync().name(T + 'merge#Labels').parameters({fromCategoryId, intoCategoryId}).call() || {}
    if (!ec.message.hasError()) message = ec.resource.expand('Labels merged; ${count} work items moved', '', {count: out.itemCount || 0})
} else ec.message.addError(ec.resource.expand('No label action ${action}', '', {action}))

docs = null
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'view'}).call() || {}
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId}).call()?.settings || {}
const own = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition({workEffortId: workEffortId, settingTypeEnumId: 'WstDocsWikiSpace'}).one()
const spaceId = own?.settingValue || null
docs = {workEffortId: workEffortId, projectName: access.project.workEffortName || workEffortId, docsOn: String(settings.WstModules || '').split(',').map((key) => key.trim()).includes('docs'),
    wikiSpaceId: null, spaceName: '', storageText: '', canView: false, canUpdate: false, missing: false, canSetup: !!access.canManage,
    canLink: !!access.canUpdate, repositoryOptions: [], linkedList: []}
if (spaceId) {
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', spaceId).disableAuthz().one()
    if (space == null) docs.missing = true
    else {
        const spaceAccess = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameters({wikiSpaceId: spaceId}).call() || {}
        ec.message.clearErrors()
        docs.wikiSpaceId = spaceId
        docs.spaceName = space.description || spaceId
        docs.canView = !!spaceAccess.canView
        docs.canUpdate = !!spaceAccess.canUpdate
        const root = String(space.rootPageLocation || '')
        docs.storageText = spaceAccess.storage === 'git' ? ec.resource.expand('In the repository ${repositoryId}, ${path}', '', {repositoryId: spaceAccess.repositoryId,
            path: root.replace(/^git:\/\/[^/]+\//, '').replace(/\.[^/.]*$/, '/')}) : L('Database files')
    }
}
// a space in a repository: those of the project the user may update, not a mirror
if (docs.canSetup && !spaceId) {
    for (const row of Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', workEffortId)
            .conditionDate('fromDate', 'thruDate', null).orderBy('repositoryId').list())) {
        ec.message.pushErrors()
        try {
            const repoAccess = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: row.repositoryId}).call() || {}
            const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', row.repositoryId).disableAuthz().one()
            if (!ec.message.hasError() && repoAccess.canUpdate && !repoAccess.archived && repo?.repositoryKind !== 'remote')
                docs.repositoryOptions.push({key: row.repositoryId, text: row.repositoryId + (repo?.description ? ' · ' + repo.description : '')})
        } catch (err) {
            ec.logger.warn(`Docs of ${workEffortId}: repository ${row.repositoryId} not read: ${err && err.message ? err.message : err}`)
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
}
// the linked pages of other spaces (WikiPageWorkEffort), those the user may view
for (const link of Array.from(ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition('workEffortId', workEffortId).list())) {
    const page = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', link.wikiPageId).disableAuthz().one()
    if (page == null || page.wikiSpaceId === spaceId) continue
    const pageAccess = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameters({wikiPageId: page.wikiPageId}).call() || {}
    ec.message.clearErrors()
    if (!pageAccess.canView) continue
    const space = ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', page.wikiSpaceId).useCache(true).disableAuthz().one()
    const path = String(page.pagePath || '')
    docs.linkedList.push({wikiPageId: page.wikiPageId, wikiSpaceId: page.wikiSpaceId, pagePath: path,
        title: path ? path.substring(path.lastIndexOf('/') + 1) : (space?.description || page.wikiSpaceId), spaceName: space?.description || page.wikiSpaceId,
        url: '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(page.wikiPageId)})
}
docs.linkedList.sort((left, right) => String(left.spaceName).localeCompare(String(right.spaceName)) || String(left.pagePath).localeCompare(String(right.pagePath)))

ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'update'}).call()
if (ec.message.hasError()) return
const pageAccess = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameters({wikiPageId: wikiPageId}).call() || {}
if (ec.message.hasError() || !pageAccess.canView) { ec.message.clearErrors(); ec.message.addError(ec.l10n.localize('Page not found')); return }
const page = ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', wikiPageId).disableAuthz().one()
const title = String(page?.pagePath || wikiPageId)
const existing = ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition({wikiPageId: wikiPageId, workEffortId: workEffortId}).one()
if (unlink) {
    if (existing != null) existing.delete()
    message = ec.resource.expand('${title} unlinked', '', {title})
    return
}
if (existing == null) ec.service.sync().name('create#mantle.work.effort.WikiPageWorkEffort').parameters({wikiPageId: wikiPageId, workEffortId: workEffortId}).call()
if (ec.message.hasError()) return
message = ec.resource.expand('${title} linked to the project', '', {title})
